#!/usr/bin/env python3
"""Java 1.21.7／1.21.8（プロトコル772）の Bedrock→Java バックエンド対応を入れる。

対象: detergentmc-bedrock の JavaBackendConnection（772 サーバーとの
入出力）と BedrockEntityTranslator／BedrockChunkTranslator（772 の
ID を 765 に正規化）。771の流儀をなぞる。

772 で新たに必要なもの（771 には無かった）は無い。771と違うのは：
- アイテム（music_disc_lava_chicken が1256番に挿入、1256番以降が+1
  ずれる）・音（music_disc.lava_chicken が939番に挿入）・絵画
  （dennis が14番に挿入）・ジュークボックスの歌（lava_chicken が
  9番に挿入）。ブロック状態・エンティティ・バイオーム・パーティクル・
  属性・エンチャント・メニュー・データコンポーネントは771と同一。
  エフェクトは Unluck→BadLuck の名前変更のみで番号は同一。
- Join Game／Player Info／Synchronize Player Position／Update Attributes／
  Client Information／Chat Message／チャンクの heightmap／パレット付き
  コンテナ／Entity Metadata の型番号／粒子IDは771と同一のため、既存の
  771分岐に772を足すだけで済む（実バニラ1.21.6のプローブで確認済み：
  heightmapは770と同じ直接配列、checksum 0x00は受け入れられた。
  1.21.7／1.21.8のプローブは未実施）。
- 属性は771と同一（attributeName772 は771と同じ内容）。
- エンティティは771と同一（happy_ghast は771・772とも56）。
- 正規化は mapEntityType772To765／mapItem772To765／
  mapBlockState772To765／mapParticle772To765（ステージBで追加済み）で行う。

それ以外は771と同形で、既存の771分岐に772を足すだけで済む。
実機 Bedrock クライアントでの確認は未実施（既存の全 Bedrock 組み合わせと同様）。
各アンカーはファイル中にちょうど1回だけ現れること。
"""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent  # detergentmc-protocol/
BEDROCK = ROOT.parent / "detergentmc-bedrock" / "src" / "main" / "java" \
    / "io" / "detergentmc" / "bedrock"


def edit(path, pairs):
    src = path.read_text(encoding="utf-8")
    for label, old, new in pairs:
        n = src.count(old)
        if n != 1:
            print(f"NG: {path.name} {label}: anchor が {n} 回見つかった（1回のはず）",
                  file=sys.stderr)
            sys.exit(1)
        src = src.replace(old, new)
        print(f"OK: {path.name} {label}")
    path.write_text(src, encoding="utf-8")


